<template><div style="width:380px;margin:15vh auto"><el-card header="EasyOps 登录"><el-input v-model="form.username"/><el-input v-model="form.password" type="password" style="margin-top:8px"/><el-button type="primary" style="width:100%;margin-top:8px" @click="login">登录</el-button><el-button style="width:100%;margin:8px 0 0" @click="init">初始化管理员</el-button></el-card></div></template><script setup>import {reactive} from "vue";import {loginApi,initAdminApi} from "../api/user";const form=reactive({username:"admin",password:"admin123"});const login=async()=>{const r=await loginApi(form);localStorage.setItem("token",r.data.access_token);location.href="/"};const init=async()=>{await initAdminApi();alert("已初始化：admin/admin123")}</script>
